pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure caller is not the current owner (address(0) initially) to test privilege change
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // Make caller the owner first by deploying as caller if possible, or by setting through test contract
        // Since constructor sets owner to deployer (this contract), we need to simulate a scenario where caller is owner
        // We can prank as the current owner to transfer ownership, but the property is about transferOwnership behavior
        // The universal rule: if transferOwnership(newOwner) succeeds, then owner() == newOwner
        // In the correct version, only the current owner can call it, and it sets owner = newOwner
        // In the buggy version, anyone can call it, and it does not change owner at all (owner stays the same)

        // First, give ownership to caller
        vm.prank(c.owner());
        c.transferOwnership(caller);

        // Now caller is the owner, and we test transferOwnership with newOwner
        bool success;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // The call should succeed (caller is owner), and owner must be newOwner
        assertTrue(success && c.owner() == newOwner);
    }
}

