pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address currentOwner, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(currentOwner != address(0));
        vm.assume(caller != currentOwner);
        vm.assume(newOwner != caller);
        vm.assume(newOwner != currentOwner);

        // Set up initial state: make `currentOwner` the owner.
        // The reference contract's constructor sets owner to address(0) initially.
        // We need someone to be the owner to call transferOwnership.
        // Since the constructor sets owner to address(0), we must first make currentOwner the owner.
        // But transferOwnership has the onlyOwner modifier, so only the current owner can call it.
        // Starting from address(0) owner, we need to bypass this? No, we must use the existing mechanism.
        // Actually, the reference contract's constructor does not initialize owner. It defaults to address(0).
        // To set an owner, only the owner can call transferOwnership.
        // Therefore, the only way to set an initial owner is if the initial owner is address(0).
        // We can prank as address(0) to set the initial owner.
        vm.prank(address(0));
        c.transferOwnership(currentOwner);

        // Now currentOwner is the owner.
        // Prank as `caller` to attempt the transfer.
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // On success, the new owner should be `newOwner`.
            assertEq(c.owner(), newOwner);
        } catch {
            // On failure, the owner should remain `currentOwner`.
            assertEq(c.owner(), currentOwner);
        }
    }
}

